class Solution {
public:
    int minimizeXor(int num1, int num2) {
        int k = __builtin_popcount(num2);
        int c = __builtin_popcount(num1);
        int x = num1;
        if (c > k) {
            int toClear = c - k;
            for (int i = 0; i < 32 && toClear > 0; i++) {
                if (x & (1 << i)) {
                    x &= ~(1 << i);
                    toClear--;
                }
            }
        } else if (c < k) {
            int toSet = k - c;
            for (int i = 0; i < 32 && toSet > 0; i++) {
                if (!(x & (1 << i))) {
                    x |= (1 << i);
                    toSet--;
                }
            }
        }
        return x;
    }
};
